pragma solidity ^0.8.0;

library SafeMath {
    function tryAdd(
        uint256 a,
        uint256 b
    ) internal pure returns (bool, uint256) {
        unchecked {
            uint256 c = a + b;
            if (c < a) return (false, 0);
            return (true, c);
        }
    }

    function trySub(
        uint256 a,
        uint256 b
    ) internal pure returns (bool, uint256) {
        unchecked {
            if (b > a) return (false, 0);
            return (true, a - b);
        }
    }

    function tryMul(
        uint256 a,
        uint256 b
    ) internal pure returns (bool, uint256) {
        unchecked {
            if (a == 0) return (true, 0);
            uint256 c = a * b;
            if (c / a != b) return (false, 0);
            return (true, c);
        }
    }

    function tryDiv(
        uint256 a,
        uint256 b
    ) internal pure returns (bool, uint256) {
        unchecked {
            if (b == 0) return (false, 0);
            return (true, a / b);
        }
    }

    function tryMod(
        uint256 a,
        uint256 b
    ) internal pure returns (bool, uint256) {
        unchecked {
            if (b == 0) return (false, 0);
            return (true, a % b);
        }
    }

    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        return a + b;
    }

    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        return a - b;
    }

    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        return a * b;
    }

    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        return a / b;
    }

    function mod(uint256 a, uint256 b) internal pure returns (uint256) {
        return a % b;
    }

    function sub(
        uint256 a,
        uint256 b,
        string memory errorMessage
    ) internal pure returns (uint256) {
        unchecked {
            require(b <= a, errorMessage);
            return a - b;
        }
    }

    function div(
        uint256 a,
        uint256 b,
        string memory errorMessage
    ) internal pure returns (uint256) {
        unchecked {
            require(b > 0, errorMessage);
            return a / b;
        }
    }

    function mod(
        uint256 a,
        uint256 b,
        string memory errorMessage
    ) internal pure returns (uint256) {
        unchecked {
            require(b > 0, errorMessage);
            return a % b;
        }
    }
}

interface IERC20 {
    function totalSupply() external view returns (uint256);

    function balanceOf(address account) external view returns (uint256);

    function transfer(
        address recipient,
        uint256 amount
    ) external returns (bool);

    function allowance(
        address owner,
        address spender
    ) external view returns (uint256);

    function approve(address spender, uint256 amount) external returns (bool);

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) external returns (bool);
}

interface IMintableToken {
    function mint(address user, uint amount) external;

    function burn(uint amount) external;
}

interface Ifactory {
    function isLink(address _link) external view returns (bool);
}

interface Ifile {
    function factory() external view returns (address);

    function luca() external view returns (address);

    function wluca() external view returns (address);

    function minter() external view returns (address);

    function agt() external view returns (address);

    function crossChain() external view returns (address);

    function accessControl() external view returns (address);
}

interface IATMAccessControl {
    function redirectTarget(address _addr) external view returns (address);
    function isBlacklisted(address _addr) external view returns (bool);
}

interface Itrader {
    function balance() external returns (uint256 luca, uint256 wluca);

    function payment(
        address _token,
        address _from,
        address _to,
        uint256 _amount
    ) external returns (bool);

    function withdrawFor(address _to, uint256 _amount) external;

    function wrapAllLuca() external;

    function suck(address _to, uint256 _amount, uint256 _lockDay) external;

    function suck(address _to, uint256 _lockDay) external;
}

interface IMinterContract {
    function convertLucaToWLuca(address _to, uint256 _amount) external;

    function convertWLucaToLuca(address _to, uint256 _amount) external;

    function burnTraderLuca(uint256 _amount) external;

    function blackList(address user) external view returns (bool);
}

interface ILinkView {
    function getLinkInfo()
        external
        view
        returns (
            string memory symbol_,
            address token_,
            address userA_,
            address userB_,
            uint256 amountA_,
            uint256 amountB_,
            uint256 percentA_,
            uint256 totalPlan_,
            uint256 lockDays_,
            uint256 startTime_,
            uint256 status_,
            bool isAward_
        );
}


contract Initialize {
    bool private initialized;

    modifier noInit() {
        require(!initialized, "initialized");
        _;
        initialized = true;
    }
}

contract Trader is Initialize, Itrader {
    using SafeMath for uint256;
    address public file;

    modifier verifyCaller() {
        address factory = Ifile(file).factory();
        address crossChain = Ifile(file).crossChain();

        bool isFactory = (msg.sender == factory);
        bool isLink = Ifactory(factory).isLink(msg.sender);
        bool isCross = (msg.sender == crossChain);

        require(isFactory || isLink || isCross, "Trader: access denied");

        if (isLink) {
            (, , address userA, address userB, , , uint256 percentA, , , , , ) = ILinkView(
                msg.sender
            ).getLinkInfo();

            address ac = Ifile(file).accessControl();
            require(ac != address(0), "accessControl not set");

            if (userA != address(0) && percentA > 0) {
                require(
                    IATMAccessControl(ac).redirectTarget(userA) != address(0),
                    "Trader: userA is blacklisted or frozen without safe wallet"
                );
            }

            if (userB != address(0) && percentA < 100) {
                require(
                    IATMAccessControl(ac).redirectTarget(userB) != address(0),
                    "Trader: userB is blacklisted or frozen without safe wallet"
                );
            }
        }

        _;
    }

    function initialize(address _file) external noInit {
        file = _file;
    }

    function balance()
        external
        view
        override
        returns (uint256 luca_balance, uint256 wluca_supply)
    {
        (address luca, address wluca) = (
            Ifile(file).luca(),
            Ifile(file).wluca()
        );
        return (
            IERC20(luca).balanceOf(address(this)),
            IERC20(wluca).totalSupply()
        );
    }

    function payment(
        address _token,
        address _from,
        address _to,
        uint256 _amount
    ) external override verifyCaller returns (bool) {
        address ac = Ifile(file).accessControl();
        require(ac != address(0), "accessControl not set");
        address _toTarget = IATMAccessControl(ac).redirectTarget(_to);
        require(_toTarget != address(0), "Trader: recipient restricted");

        (address luca, address wluca, address minter) = (
            Ifile(file).luca(),
            Ifile(file).wluca(),
            Ifile(file).minter()
        );
        if (_token == luca) {
            IERC20(luca).transferFrom(_from, minter, _amount);
            IMinterContract(minter).convertLucaToWLuca(address(this), _amount);
            IERC20(wluca).approve(address(this), _amount);
            require(
                IERC20(wluca).transfer(_toTarget, _amount),
                "Trader: not enough allowed wluca"
            );

            return true;
        }

        return IERC20(_token).transferFrom(_from, _toTarget, _amount);
    }

    function withdrawFor(
        address _to,
        uint256 _amount
    ) external override verifyCaller {
        address ac = Ifile(file).accessControl();
        require(ac != address(0), "accessControl not set");
        address _toTarget = IATMAccessControl(ac).redirectTarget(_to);
        require(_toTarget != address(0), "Trader: recipient restricted");

        (address luca, address wluca, address minter) = (
            Ifile(file).luca(),
            Ifile(file).wluca(),
            Ifile(file).minter()
        );
        require(
            IERC20(wluca).transferFrom(msg.sender, address(this), _amount),
            "Trader: not enough allowed wluca"
        );
        IERC20(wluca).approve(address(this), _amount);
        require(
            IERC20(wluca).transfer(minter, _amount),
            "Trader: not enough allowed wluca"
        );
        IMinterContract(minter).convertWLucaToLuca(address(this), _amount);
        require(IERC20(luca).transfer(_toTarget, _amount), "Trader: luca transfer failed");
    }

    function wrapAllLuca() external override {
        (address luca, address minter) = (
            Ifile(file).luca(),
            Ifile(file).minter()
        );
        uint256 luca_balance = IERC20(luca).balanceOf(address(this));
        IERC20(luca).transfer(minter, luca_balance);
        IMinterContract(minter).burnTraderLuca(luca_balance);
    }

    function suck(
        address _to,
        uint256 _amount,
        uint256 _lockDay
    ) external override verifyCaller {
        // v1.0.5: check the recipient BEFORE the zero-award early return. A Link calls suck(userB, 0, ..)
        // from setUserB on an open 100% LUCA Link; in v1.0.4 the 0 award returned before the ACL
        // check, so a blacklisted / frozen-without-safe wallet could be set as user B.
        address ac = Ifile(file).accessControl();
        require(ac != address(0), "accessControl not set");
        address _toTarget = IATMAccessControl(ac).redirectTarget(_to);
        require(_toTarget != address(0), "Trader: recipient restricted");
        uint256 award = _amount.mul(_lockDay).div(100).div(10 ** 18);
        if (award == 0) return;
        address agt = Ifile(file).agt();
        IMintableToken(agt).mint(_toTarget, award.mul(10 ** 18));
    }

    function suck(address _to, uint256 _amount) external override verifyCaller {
        address ac = Ifile(file).accessControl();
        require(ac != address(0), "accessControl not set");
        address _toTarget = IATMAccessControl(ac).redirectTarget(_to);
        require(_toTarget != address(0), "Trader: recipient restricted");
        address agt = Ifile(file).agt();
        IMintableToken(agt).mint(_toTarget, _amount);
    }

    function version() external pure returns (string memory) {
        return "v1.0.5";
    }
}
